insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('793e1e7e-18ac-50b8-bd93-7dc30ed036a3', 'treadmill-starter', '跑步机新手起步', '走跑结合，4 周从快走过渡到连续慢跑', '完全没跑过步也能跟：每周 3 次，用快走打底，再把一分钟、两分钟的慢跑小段一点点接起来。强度以能轻松说话为准，重点是养成习惯而不是跑多快。', '第 1–2 周按安排完成；第 3–4 周把慢跑段各加 1 分钟、组间走路减少到 60 秒。', '有氧跟练', 1, 4, 3, 35, 'A.B.C..', array['健身房']::text[], array['新手','久坐上班族']::text[], array['跑步机']::text[], false, true, 0);
