insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('28d0277c-a06d-5b01-8b0c-4d3076e65a02', 'treadmill-incline-burn', '跑步机坡度走燃脂', '不跑也能燃脂，用坡度提高消耗', '把坡度调高、速度放慢，臀腿的参与会更多，膝盖压力又比跑步小。每次 30 分钟左右，适合不喜欢跑步或者刚开始运动的人。', '每 1–2 周把主段坡度调高 1–2%，但速度不要超过 5.5 公里/小时。', '有氧跟练', 1, 4, 3, 35, 'A.B.C..', array['健身房']::text[], array['新手','女性','久坐上班族']::text[], array['跑步机']::text[], true, false, 1);
