insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('f2a32a28-41fa-5223-83cb-7e3f14988f13', 'fatloss-glute-leg', '臀腿脂肪速燃', '大肌群练得多，消耗就高', '臀和腿是全身最大的肌群，练它们的热量消耗也最高。这个计划用深蹲、臀桥、硬拉铰链等基础动作，每次都以臀腿大肌群开始，打下“先稳后重”的基础。', '第 1–2 周用能做满次数的重量；第 3–4 周在每个动作最后加一组，重量不变。', '瘦身减脂', 1, 4, 3, 35, 'A.B.C..', array['健身房','居家']::text[], array['新手','女性']::text[], array['壶铃','固定器械','哑铃','杠铃','绳索']::text[], false, false, 17);
