insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('59ea42b2-3667-5bd0-981a-9d95f6d89820', 'shape-hourglass', '沙漏曲线 8 周', '练肩、背和臀腿，把腰线衬托出来', '沙漏曲线的关键是肩宽、腰细、臀圆。这个计划每周 4 练：两天练肩背，两天练臀腿，腹部通过核心动作配合，让比例更协调。', '前 4 周以每个动作 3 组为主，后 4 周在主要动作上增加到 4 组，并略微加重。', '塑形美体', 2, 8, 4, 40, 'AB.CD..', array['健身房']::text[], array['女性','有基础者']::text[], array['哑铃','绳索','杠铃','固定器械']::text[], false, false, 26);
