insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('f0de63e5-e837-5cfa-8f96-6a95959f9ac6', 'shape-once-a-week', '每周一练 · 全身维持', '太忙时的最低有效剂量，一周只练一次', '每周只练一次 45 分钟，覆盖全身所有大肌群，用中等重量做 2–3 组。它不会让你进步很快，但能让身体保持习惯、保持线条，也很适合作为恢复期的维持计划。', '每个动作保持 2–3 组、留 2 次力竭余量；稳定做满 4 周后可以把训练日加到每周 2 次。', '塑形美体', 1, 8, 1, 40, 'A......', array['健身房','居家']::text[], array['久坐上班族','新手','中老年']::text[], array['壶铃','哑铃','绳索','杠铃']::text[], false, false, 27);
