insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('528ec8aa-f0c0-5994-ad66-fffce93a9181', 'muscle-barbell-novice', '新手杠铃入门', '三个基础动作起步，每次练都能加一点重量', '新手阶段进步最快，只需要把深蹲、卧推、硬拉、推举、划船这几个基础动作练扎实。两节课交替做，每次都尽量比上次多一点点重量，8 周后你会感受到明显的力量提升。', '能完成所有组次数时，下次上肢动作加 2.5 公斤、下肢动作加 5 公斤；卡住时先保持重量再练一次。', '增肌增重', 1, 8, 3, 40, 'A.B.A..', array['健身房']::text[], array['新手','男性','女性']::text[], array['杠铃','绳索']::text[], false, true, 28);
