insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('39f61b17-fa69-511d-b473-768d1f1cb883', 'muscle-dumbbell-novice', '新手哑铃增肌', '一对哑铃就能全身增肌，适合家里或健身房', '哑铃让每一侧各自发力，更容易发现力量的左右差异，动作幅度也更自由。每周 3 次全身训练，每个部位被刺激两次以上，是增肌初期很有效的安排。', '每个动作先做到上限次数，满足后再加最小一级哑铃；每 4 周回顾一次重量。', '增肌增重', 1, 8, 3, 35, 'A.B.C..', array['健身房','居家']::text[], array['新手','男性','女性']::text[], array['壶铃','哑铃']::text[], false, false, 29);
