insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('cee22ead-1916-5005-b180-5c9d1e15e71f', 'muscle-upper-lower', '上下肢分化增肌', '上肢和下肢各练两次，兼顾频率与恢复', '每个肌群每周被训练两次，是目前被验证很有效的增肌频率。两个上肢日、两个下肢日，一个侧重力量（6–10 次），另一个侧重肌肥大（10–15 次）。', '力量日每周尝试在主要动作上加 1–2 次或加重 2.5%；肌肥大日每个动作做到接近力竭。', '增肌增重', 2, 8, 4, 50, 'AB.CD..', array['健身房']::text[], array['有基础者','男性']::text[], array['杠铃','绳索','EZ 杠','固定器械','哑铃']::text[], false, false, 31);
