insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('ce3db8c2-8d28-5269-ad6c-921d1b88d841', 'muscle-five-split', '五分化增肌', '胸、背、肩、腿、手臂各练一天，每次集中火力', '每天只练一个部位，所以可以把该部位的动作做得很全、很累。适合训练经验一年以上、每周可以练 5 天的人。注意：每个肌群每周只被刺激一次，所以每个部位的训练要足够用力。', '每个部位第 1–4 周保持每个动作 3–4 组；第 5–8 周在前两个动作各加一组。', '增肌增重', 2, 8, 5, 45, 'ABCDE..', array['健身房']::text[], array['有基础者','男性']::text[], array['杠铃','哑铃','绳索','凳子/单杠','固定器械','EZ 杠']::text[], false, false, 33);
