insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('e89177d5-f51b-53a4-b29e-7faa3b349994', 'muscle-leg-mass', '腿部围度专项', '前侧、后侧和小腿都有量，才不会腿细上身粗', '一周三次腿日：股四头肌日、腘绳肌与臀日、综合日，让大腿前后侧均衡发展。腿部训练非常消耗，每次课后记得充足睡眠和蛋白质摄入。', '每周在深蹲和硬拉类动作上加一点重量；若恢复不过来，把中间一次减为 2 组。', '增肌增重', 2, 6, 3, 40, 'A.B.C..', array['健身房']::text[], array['有基础者','男性','女性']::text[], array['杠铃','固定器械','凳子/单杠','哑铃']::text[], false, false, 42);
