insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('9b54ccb5-8e2e-5ba9-b9a1-6ec2322f299a', 'health-round-shoulder', '圆肩驼背改善', '先放松胸前，再练强背部，让肩膀回到该有的位置', '久坐低头会让胸肌变短、背部变弱，肩膀就会往前。这个计划交替安排“拉伸胸前”与“强化背部”的小训练，每次约 20 分钟，每周 4 次，坚持 6 周能明显感受到站姿更开阔。', '每两周在强化动作上多做 1 组；每次训练后做一次站姿自查（靠墙站，后脑勺、肩胛、臀部能否贴墙）。', '健康改善', 1, 6, 4, 20, 'AB.AB..', array['居家','健身房']::text[], array['久坐上班族','新手','女性','男性']::text[], array['弹力带','绳索','哑铃']::text[], false, false, 43);
