insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('2ec2b6ae-8681-51ea-a08d-9c77020b16bb', 'health-uneven-shoulder', '高低肩调整', '两边对称地练，再单独补弱的一侧', '高低肩常常与单侧习惯（单肩包、托腮）有关。计划用单侧动作找出两边的差异，从较弱的一侧开始做、做同样次数；同时放松偏紧的一侧，帮助肩带回到更对称的位置。', '每次训练先做较弱的一侧，另一侧不要超过该次数；第 3–4 周再增加弹力带阻力。', '健康改善', 1, 4, 3, 20, 'A.B.C..', array['居家','健身房']::text[], array['久坐上班族','新手','女性','男性']::text[], array['哑铃','弹力带','绳索']::text[], false, false, 44);
