insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('08c1e629-0077-5064-bd23-5c9cb30a0142', 'health-winged-scapula', '翼状肩与肩胛稳定', '把肩胛骨“压”回胸廓上，激活前锯肌与下斜方', '翼状肩多与前锯肌无力有关。这个计划围绕肩胛骨的前伸与下沉：肩胛俯卧撑练前锯肌、Y-T-W 与靠墙滑动练下斜方、肩袖外旋练稳定。动作都很轻，重在慢和准。', '每个动作用 2–3 组，每次都要求动作控制在 3 秒上、3 秒下；肩膀不适时降低幅度。', '健康改善', 1, 6, 3, 20, 'A.B.A..', array['居家','健身房']::text[], array['新手','久坐上班族','女性','男性']::text[], array['弹力带','绳索','哑铃']::text[], false, false, 46);
