insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('54f4c94d-2cde-5f64-8e55-5af2ee07940b', 'health-low-back', '腰背稳定与护腰', '先稳住躯干，再谈力量', '腰背不适的人往往核心深层肌与臀部较弱。计划用鸟狗式、死虫式、臀桥这类“稳定为先”的动作，加上髋铰链的学习，让腰背在日常和训练中少受力。若已有疼痛，请先咨询医生。', '每两周把保持时间多加 5 秒或增加 1 组；出现疼痛立即停止，并回到前一阶段。', '健康改善', 1, 6, 3, 20, 'A.B.C..', array['居家','健身房']::text[], array['久坐上班族','新手','中老年','男性','女性']::text[], array['徒手']::text[], false, false, 47);
