insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('136c1736-c2b6-5110-b244-d57062996569', 'stretch-legs-foam', '腿部拉伸与泡沫轴恢复', '腿日之后的恢复套餐：滚一滚、拉一拉', '腿部肌肉大，练完常常酸到上下楼困难。用泡沫轴滚动配合静态拉伸，对缓解延迟性肌肉酸痛有帮助。滚动速度要慢（每秒约 2–3 厘米），遇到敏感点停留，不要压在关节上。', '第 3–4 周把每个滚动动作的时间延长 15 秒；拉伸时每次尽量比上次多深入一点点。', '拉伸放松', 1, 4, 4, 5, 'AB.AB..', array['居家','健身房']::text[], array['新手','有基础者','男性','女性']::text[], array['泡沫轴']::text[], false, false, 58);
