insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('72440c27-4bcb-5fea-9d1b-b65071c8d8f2', 'glute-barbell-thrust', '杠铃臀推进阶', '以臀推为核心，每周三次变化角度', '杠铃臀推是练臀部最直接的动作之一。计划围绕它安排三种强度：力量日（低次数、重）、肌肥大日（中次数）、耐力日（高次数），其余动作做补充，让臀部各个方向都练到。', '臀推的重量每周按 2.5–5 公斤提升；卡住时保持重量再做一周。每 4 周安排一周减量。', '丰满翘臀', 3, 8, 3, 40, 'A.B.C..', array['健身房']::text[], array['女性','有基础者']::text[], array['杠铃','哑铃','固定器械','绳索','弹力带']::text[], false, false, 63);
