insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('030ddb84-1f46-58a6-9ac1-8ddb6dd3c5e1', 'activate-glute-leg', '练腿前臀腿激活', '八分钟让臀中肌和臀大肌先醒过来', '很多人深蹲、硬拉时臀部总是发不上力。在正式训练前花八分钟，用小幅度、慢速度的臀桥、蚌式开合和侧向行走把臀部叫醒，再进入大重量动作会顺手很多。', '第 1–2 周每个动作 2 组；第 3–4 周在臀桥和怪兽步里加弹力带，顶点停留 2 秒。', '激活热身', 1, 4, 4, 10, 'A.B.A.B', array['居家','健身房']::text[], array['新手','女性','男性','有基础者']::text[], array['弹力带']::text[], false, false, 68);
