insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('ade0dde4-116b-5eef-98b9-623ddf3cff85', 'activate-upper-scapula', '练上肢前肩胛激活', '推拉之前，先让肩胛骨找到位置', '卧推、肩推、划船时，如果肩胛骨不稳，肩前侧就容易代偿。这套激活用弹力带和自重动作，在 8–10 分钟里唤醒肩袖、前锯肌和中下斜方，让训练更安全也更好发力。', '每周把弹力带换紧一档，或把每组停留时间延长 1 秒；动作质量下降就停。', '激活热身', 1, 4, 4, 15, 'A.B.A.B', array['居家','健身房']::text[], array['新手','久坐上班族','男性','女性']::text[], array['弹力带']::text[], false, false, 69);
