insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('efcfc962-138d-5d2b-b22d-2e29e1337093', 'activate-core-stability', '核心稳定激活', '练好腹横肌和深层稳定，大重量时腰才稳', '核心不是练到卷腹卷到酸，而是在四肢动作时保持脊柱不晃。用死虫式、鸟狗式和侧平板这些低负荷动作，先把深层稳定肌激活，再去做深蹲、硬拉会更踏实。', '第 1–2 周每个动作 2 组；第 3–4 周把保持时间加长 5–10 秒，动作慢一点。', '激活热身', 1, 4, 4, 10, 'A.B.A.B', array['居家']::text[], array['新手','久坐上班族','女性','男性']::text[], array['徒手']::text[], false, false, 70);
