insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('f3dc69ae-6d14-5371-9738-1bc2e3d4c1dc', 'activate-morning-10', '晨起唤醒十分钟', '起床后十分钟，把一整晚的僵硬动开', '不出汗、不累，只用缓慢的活动度动作把脊柱、髋、肩和踝关节依次动开，再配合几次深呼吸。适合上班前、训练前，也适合早晨起来觉得“整个人不在状态”的时候。', '每天做一遍；觉得轻松后，把每个动作的次数多加 2–4 次，但不要追求幅度更大。', '激活热身', 1, 4, 5, 10, 'AAAAA..', array['居家']::text[], array['新手','久坐上班族','中老年','女性','男性']::text[], array['徒手']::text[], false, false, 71);
