insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('720d21a8-ed25-5f50-8b8f-02a184d54777', 'activate-desk-reset', '久坐上班族重启', '坐了一天，傍晚用十分钟把身体重新打开', '久坐会让髋屈肌变短、臀部“睡着”、胸椎僵硬、头前伸。这套动作分成两个小节：A 唤醒被压扁的臀部和肩背，B 松开髋前和胸椎。每次十分钟，办公室小空间也能做。', '每周多做 1 组；站着办公的人可以只做 A。', '激活热身', 1, 4, 4, 10, 'A.B.A.B', array['居家']::text[], array['久坐上班族','新手','女性','男性']::text[], array['徒手']::text[], false, false, 72);
