insert into public.programs (id, slug, name, subtitle, description, progression, category, level, weeks, days_per_week, minutes, schedule, scenes, audiences, equipment, is_new, featured, sort_order) values ('76d4fb54-b605-56bc-a3a0-61323b15bd3f', 'activate-runner', '跑前动态热身 + 跑后放松', 'A 在跑步前做，B 在跑步后做，各约八分钟', '跑步前不要只靠慢跑热身：先用摆腿、踝背屈和小幅度高抬腿把髋、踝、小腿唤醒。跑完再用小腿、大腿前后侧和臀部的拉伸降温，能减少第二天的紧绷。', '每次跑步都配套做；如果某个部位总是特别紧，在对应拉伸上多加 1 组。', '激活热身', 1, 4, 4, 5, 'A.B.A.B', array['户外','健身房']::text[], array['新手','有基础者','男性','女性']::text[], array['徒手']::text[], false, false, 73);
